// Industries hub + industry pages, written from the briefs in plan/content-plan.json.
// Every industry page covers the plan's outline, but each page has its own H2 wording, section order,
// FAQs, table columns and reach paragraph, so the seven pages never read as copies with a name swapped
// (audit 2026-10-23, F54 swap test). Area links appear automatically once the /areas/ pages are built.
// Regulator facts were checked on the regulator's own site on 2026-10-22 (see plan/fixes-content-3.md).
// Inline marks: [[placeholder]]  **bold**  {{link text|slug}}  ({{text|}} links to the homepage)
import type { Page } from './types';

const UPDATED = '2026-10-23';
const G_LOCAL = ['Google Business Profile Help: How to improve your local ranking', 'https://support.google.com/business/answer/7091?hl=en'];
const G_REVIEWS = ['Google Maps user-generated content policy: Prohibited and restricted content', 'https://support.google.com/contributionpolicy/answer/7400114?hl=en'];
const TOWNS = '{{St. Albert|areas/st-albert}}, {{Sherwood Park|areas/sherwood-park}}, {{Spruce Grove|areas/spruce-grove}}, {{Leduc|areas/leduc}} and {{Fort Saskatchewan|areas/fort-saskatchewan}}';

type Key = 'why' | 'search' | 'mapPack' | 'seasonal' | 'trust' | 'results' | 'nearby';

type Industry = {
  slug: string; nav: string; crumb: string; plural: string; icon: string; illus: string; keyword: string;
  title: string; description: string; h1: string; lead: string; card: string; audience: string;
  order: Key[]; // the page's own section order between the hero and the FAQ
  h: Record<Key | 'faq' | 'services' | 'cta', string>; // every H2 is written for this industry
  why: string[]; whyBullets: string[];
  serp: { query: string; rows: string[] }; searchIntro: string; searches: [string, string][];
  mapPackIntro: string; cardTitles: [string, string, string, string]; mapPack: { profile: string; pages: string; reviews: string; citations: string };
  seasonal: string[]; trustIntro: string; trust: [string, string][];
  resultsIntro: string; cols: string[]; results: string[][];
  nearby: string[]; faqIntro: string; faq: [string, string][];
  servicesIntro: string; services: string[]; ctaText: string; sources?: string[][];
};

function industry(o: Industry): Page {
  const block: Record<Key, any> = {
    why: { type: 'split', eyebrow: 'Why it matters', heading: o.h.why, visual: 'map', vdata: { title: 'Your business', sub: 'Top 3 for your main service' }, body: o.why, bullets: o.whyBullets },
    search: { type: 'split', eyebrow: 'Search demand', heading: o.h.search, reverse: true, bg: 'soft', visual: 'serp', vdata: o.serp, body: [o.searchIntro], bullets: o.searches.map(([q, note]) => `**${q}**: ${note}`) },
    mapPack: { type: 'cards', eyebrow: 'Our approach', heading: o.h.mapPack, intro: o.mapPackIntro, cols: 4, items: [
      { icon: 'store', title: o.cardTitles[0], text: o.mapPack.profile },
      { icon: 'doc', title: o.cardTitles[1], text: o.mapPack.pages },
      { icon: 'star', title: o.cardTitles[2], text: o.mapPack.reviews },
      { icon: 'link', title: o.cardTitles[3], text: o.mapPack.citations }] },
    seasonal: { type: 'prose', blocks: [['h2', o.h.seasonal], ...o.seasonal.map((t) => ['p', t])] },
    trust: { type: 'checklist', eyebrow: 'Trust', heading: o.h.trust, intro: o.trustIntro, items: o.trust },
    results: { type: 'table', eyebrow: 'Measurement', heading: o.h.results, intro: o.resultsIntro, cols: o.cols, rows: o.results },
    nearby: { type: 'prose', blocks: [['h2', o.h.nearby], ...o.nearby.map((t) => ['p', t]), ['src', [G_LOCAL, G_REVIEWS, ...(o.sources ?? [])]]] },
  };
  return {
    slug: 'industries/' + o.slug, nav_label: o.nav, icon: o.icon, illus: o.illus, title: o.title, description: o.description, keyword: o.keyword,
    card: o.card, crumbs: [['Industries', 'industries']], service: `SEO for ${o.plural} in Edmonton`, audience: o.crumb, area: 'Edmonton, AB',
    updated: UPDATED,
    sections: [
      { type: 'page_hero', eyebrow: 'Industries · ' + o.crumb, h1: o.h1, lead: o.lead, cta: ['Get a free SEO audit', 'free-seo-audit'] },
      ...o.order.map((k) => block[k]),
      { type: 'faq', eyebrow: 'FAQ', heading: o.h.faq, intro: o.faqIntro, items: o.faq },
      { type: 'links', eyebrow: 'Services', heading: o.h.services, intro: o.servicesIntro, items: o.services, bg: 'soft' },
      { type: 'cta', heading: o.h.cta, text: o.ctaText, button: ['Get a free SEO audit', 'free-seo-audit'] },
    ],
  };
}

